begin;
-- Decimal strings preserve exact values through PostgREST JSON, with database validation.
create function private.valid_rounding(v jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(v)='object' and v->>'mode' in ('none','nearest','up','down') and v->>'step' ~ '^(0|[1-9][0-9]{0,11})(\.[0-9]{1,6})?$' and (v->>'step')::numeric>0,false);
$$;
create table public.units(key text primary key, label text not null, dimension text not null check(dimension in ('area','length','volume','count','scalar','percentage','custom')));
create table public.measurement_methods(key text primary key, label text not null, dimension text not null, fields jsonb not null);
insert into public.units values ('sq_ft','Square foot (dimensions in feet)','area'),('sq_m','Square metre (dimensions in metres)','area'),('running_ft','Running foot','length'),('running_m','Running metre','length'),('cubic_ft','Cubic foot (dimensions in feet)','volume'),('cubic_m','Cubic metre (dimensions in metres)','volume'),('each','Each','count'),('point','Point','count'),('room','Room','count'),('day','Day','count'),('hour','Hour','count'),('lump_sum','Lump sum','scalar'),('percentage','Percentage','percentage'),('package','Package','scalar'),('custom','Custom quantity','custom');
insert into public.measurement_methods values ('manual','Manual quantity','custom','["quantity"]'),('width_height','Width × Height','area','["width","height"]'),('length','Length','length','["length"]'),('area','Length × Width','area','["length","width"]'),('volume','Length × Width × Height','volume','["length","width","height"]'),('count','Count','count','["quantity"]'),('lump_sum','Lump sum (one)','scalar','[]'),('percentage','Percentage of base rate','percentage','["percentage"]');
create table public.catalog_categories (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), name text not null check(length(trim(name)) between 1 and 200), key text not null check(key ~ '^[a-z][a-z0-9_]*$' and length(key)<=64), description text not null default '' check(length(description)<=2000), sort_order integer not null default 0, industry_id uuid references public.industries(id), parent_id uuid, unique(organization_id,key), foreign key(organization_id,parent_id) references public.catalog_categories(organization_id,id));
create table public.catalog_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), name text not null check(length(trim(name)) between 1 and 200), key text not null check(key ~ '^[a-z][a-z0-9_]*$' and length(key)<=64), description text not null default '' check(length(description)<=2000), sort_order integer not null default 0, category_id uuid, industry_id uuid references public.industries(id), unit_key text not null references public.units(key), method_key text not null references public.measurement_methods(key), quantity_rounding jsonb not null default '{"mode":"none","step":"0.01"}', amount_rounding jsonb not null default '{"mode":"nearest","step":"0.01"}', unique(organization_id,key), foreign key(organization_id,category_id) references public.catalog_categories(organization_id,id), check(private.valid_rounding(quantity_rounding)), check(private.valid_rounding(amount_rounding)));
create table public.catalog_item_attributes (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), item_id uuid not null, key text not null check(key ~ '^[a-z][a-z0-9_]*$' and length(key)<=64), label text not null check(length(trim(label)) between 1 and 200), input_type text not null check(input_type in ('select','multi_select','boolean','number','text')), required boolean not null default false, visible_sales boolean not null default true, visible_customer boolean not null default true, affects_pricing boolean not null default false, default_options jsonb not null default '[]' check(jsonb_typeof(default_options)='array' and jsonb_array_length(default_options)<=100), conditions jsonb not null default '[]' check(jsonb_typeof(conditions)='array' and jsonb_array_length(conditions)<=20), help_text text not null default '' check(length(help_text)<=1000), sort_order integer not null default 0, unique(organization_id,item_id,id), unique(item_id,key), foreign key(organization_id,item_id) references public.catalog_items(organization_id,id));
create table public.catalog_attribute_options (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), item_id uuid not null, attribute_id uuid not null, key text not null check(key ~ '^[a-z][a-z0-9_]*$' and length(key)<=64), label text not null check(length(trim(label)) between 1 and 200), description text not null default '' check(length(description)<=2000), sort_order integer not null default 0, unique(organization_id,item_id,id), unique(attribute_id,key), foreign key(organization_id,item_id,attribute_id) references public.catalog_item_attributes(organization_id,item_id,id));
create table public.price_books (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), name text not null check(length(trim(name)) between 1 and 200), key text not null check(key ~ '^[a-z][a-z0-9_]*$' and length(key)<=64), currency text not null check(currency ~ '^[A-Z]{3}$'), branch_id uuid, is_default boolean not null default false, valid_from timestamptz not null, valid_until timestamptz, check(valid_until is null or valid_until>valid_from), unique(organization_id,key), foreign key(organization_id,branch_id) references public.branches(organization_id,id));
create table public.price_book_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), item_id uuid not null, price_book_id uuid, currency text not null check(currency ~ '^[A-Z]{3}$'), base_rate text not null check(base_rate ~ '^(0|[1-9][0-9]{0,11})(\.[0-9]{1,6})?$'), minimum_rate text  check(minimum_rate ~ '^(0|[1-9][0-9]{0,11})(\.[0-9]{1,6})?$'), valid_from timestamptz not null, valid_until timestamptz, check(valid_until is null or valid_until>valid_from), foreign key(organization_id,item_id) references public.catalog_items(organization_id,id), foreign key(organization_id,price_book_id) references public.price_books(organization_id,id));
create table public.pricing_modifiers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), item_id uuid not null, option_id uuid, price_book_id uuid, label text not null check(length(trim(label)) between 1 and 200), kind text not null check(kind in ('per_unit','fixed','percentage')), value text not null check(value ~ '^-?(0|[1-9][0-9]{0,11})(\.[0-9]{1,6})?$'), sort_order integer not null default 0, check(kind<>'percentage' or value::numeric between -100 and 1000), foreign key(organization_id,item_id) references public.catalog_items(organization_id,id), foreign key(organization_id,item_id,option_id) references public.catalog_attribute_options(organization_id,item_id,id), foreign key(organization_id,price_book_id) references public.price_books(organization_id,id));
create table public.pricing_costs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), version integer not null default 1 check(version>0), status text not null default 'active' check(status in ('active','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), rate_id uuid not null, estimated_cost_rate text not null check(estimated_cost_rate ~ '^(0|[1-9][0-9]{0,11})(\.[0-9]{1,6})?$'), unique(rate_id), foreign key(organization_id,rate_id) references public.price_book_items(organization_id,id));
create index rate_resolution on public.price_book_items(organization_id,item_id,price_book_id,valid_from);
create index modifier_item on public.pricing_modifiers(organization_id,item_id);
create index options_attribute on public.catalog_attribute_options(organization_id,attribute_id);
create unique index one_book_default on public.price_books(organization_id,currency,coalesce(branch_id,'00000000-0000-0000-0000-000000000000'::uuid)) where is_default and status='active';
alter table public.units enable row level security; alter table public.units force row level security;
revoke all on public.units from public,anon,authenticated; grant select on public.units to authenticated;
create policy scoped_read on public.units for select to authenticated using(private.is_active_user());
alter table public.measurement_methods enable row level security; alter table public.measurement_methods force row level security;
revoke all on public.measurement_methods from public,anon,authenticated; grant select on public.measurement_methods to authenticated;
create policy scoped_read on public.measurement_methods for select to authenticated using(private.is_active_user());
alter table public.catalog_categories enable row level security; alter table public.catalog_categories force row level security;
revoke all on public.catalog_categories from public,anon,authenticated; grant select on public.catalog_categories to authenticated;
create policy scoped_read on public.catalog_categories for select to authenticated using(private.has_permission(organization_id,'catalog.view') and public.has_entitlement(organization_id,'catalog'));
create trigger touch_updated_at before update on public.catalog_categories for each row execute function private.touch_updated_at();
alter table public.catalog_items enable row level security; alter table public.catalog_items force row level security;
revoke all on public.catalog_items from public,anon,authenticated; grant select on public.catalog_items to authenticated;
create policy scoped_read on public.catalog_items for select to authenticated using(private.has_permission(organization_id,'catalog.view') and public.has_entitlement(organization_id,'catalog'));
create trigger touch_updated_at before update on public.catalog_items for each row execute function private.touch_updated_at();
alter table public.catalog_item_attributes enable row level security; alter table public.catalog_item_attributes force row level security;
revoke all on public.catalog_item_attributes from public,anon,authenticated; grant select on public.catalog_item_attributes to authenticated;
create policy scoped_read on public.catalog_item_attributes for select to authenticated using(private.has_permission(organization_id,'catalog.view') and public.has_entitlement(organization_id,'catalog'));
create trigger touch_updated_at before update on public.catalog_item_attributes for each row execute function private.touch_updated_at();
alter table public.catalog_attribute_options enable row level security; alter table public.catalog_attribute_options force row level security;
revoke all on public.catalog_attribute_options from public,anon,authenticated; grant select on public.catalog_attribute_options to authenticated;
create policy scoped_read on public.catalog_attribute_options for select to authenticated using(private.has_permission(organization_id,'catalog.view') and public.has_entitlement(organization_id,'catalog'));
create trigger touch_updated_at before update on public.catalog_attribute_options for each row execute function private.touch_updated_at();
alter table public.price_books enable row level security; alter table public.price_books force row level security;
revoke all on public.price_books from public,anon,authenticated; grant select on public.price_books to authenticated;
create policy scoped_read on public.price_books for select to authenticated using(private.has_permission(organization_id,'catalog.view') and public.has_entitlement(organization_id,'catalog') and private.has_permission(organization_id,'pricing.view') and public.has_entitlement(organization_id,'pricing'));
create trigger touch_updated_at before update on public.price_books for each row execute function private.touch_updated_at();
alter table public.price_book_items enable row level security; alter table public.price_book_items force row level security;
revoke all on public.price_book_items from public,anon,authenticated; grant select on public.price_book_items to authenticated;
create policy scoped_read on public.price_book_items for select to authenticated using(private.has_permission(organization_id,'catalog.view') and public.has_entitlement(organization_id,'catalog') and private.has_permission(organization_id,'pricing.view') and public.has_entitlement(organization_id,'pricing'));
create trigger touch_updated_at before update on public.price_book_items for each row execute function private.touch_updated_at();
alter table public.pricing_modifiers enable row level security; alter table public.pricing_modifiers force row level security;
revoke all on public.pricing_modifiers from public,anon,authenticated; grant select on public.pricing_modifiers to authenticated;
create policy scoped_read on public.pricing_modifiers for select to authenticated using(private.has_permission(organization_id,'catalog.view') and public.has_entitlement(organization_id,'catalog') and private.has_permission(organization_id,'pricing.view') and public.has_entitlement(organization_id,'pricing'));
create trigger touch_updated_at before update on public.pricing_modifiers for each row execute function private.touch_updated_at();
alter table public.pricing_costs enable row level security; alter table public.pricing_costs force row level security;
revoke all on public.pricing_costs from public,anon,authenticated; grant select on public.pricing_costs to authenticated;
create policy scoped_read on public.pricing_costs for select to authenticated using(private.has_permission(organization_id,'catalog.view') and public.has_entitlement(organization_id,'catalog') and private.has_permission(organization_id,'pricing.view') and public.has_entitlement(organization_id,'pricing') and private.has_permission(organization_id,'quotation.view_internal_cost'));
create trigger touch_updated_at before update on public.pricing_costs for each row execute function private.touch_updated_at();
revoke all on function private.valid_rounding(jsonb) from public,anon,authenticated;
commit;
